var ErrorCodeSchema = Type.Unsafe(Type.Union(Object.keys(ERROR_CODES).map((code) => Type.Literal(code))));
function isErrorCode(code) {
  return typeof code === "string" && Object.hasOwn(ERROR_CODES, code);
}
function normalizeExternalErrorCode(code) {
  if (isErrorCode(code))
    return { code };
  return {
    code: "unclassified_error",
    audit: { originalCode: code }
  };
}

